// SPDX-License-Identifier: CC0-1.0
pragma solidity 0.8.37;

contract EvaluationOrder {
    uint256 public counter;
    event Seen(uint256 first, uint256 second);

    function next() internal returns (uint256) {
        counter += 1;
        return counter;
    }

    function binary() external returns (uint256) {
        return next() * 10 + next();
    }

    function arguments() external returns (uint256) {
        return combine(next(), next());
    }

    function emitArguments() external {
        emit Seen(next(), next());
    }

    function combine(uint256 x, uint256 y) internal pure returns (uint256) {
        return x * 10 + y;
    }
}

testdata/frontend/storage_references.sol.content:
// SPDX-License-Identifier: CC0-1.0
pragma solidity 0.8.37;

contract StorageReferences {
    struct Item {
        uint128 a;
        uint128 b;
    }

    Item[] public items;
    mapping(address => Item) public byOwner;

    function push(uint128 a, uint128 b) external {
        items.push(Item(a, b));
    }

    function capturedThenPop(uint256 i) external returns (uint128) {
        Item storage p = items[i];
        items.pop();
        return p.a;
    }

    function updateOwner(address owner, uint128 a, uint128 b) external {
        Item storage p = byOwner[owner];
        p.a = a;
        p.b = b;
    }
}

testdata/frontend/types.sol.content:
// SPDX-License-Identifier: CC0-1.0
pragma solidity 0.8.37;

contract Types {
    type Price is uint128;

    enum State { Empty, Ready }

    struct Pair {
        uint128 left;
        int64 right;
    }

    function conversions(uint8 x, int16 y, bytes4 z)
        external
        pure
        returns (uint256, int256, bytes32)
    {
        return (uint256(x), int256(y), bytes32(z));
    }

    function located(uint256[] calldata xs)
        external
        pure
        returns (uint256[] memory ys)
    {
        ys = xs;
    }
}

